language arduino
// Stepper motor on A4988 driver: moves 800 steps forward and back repeatedly.
// Wiring: STEP -> pin 3, DIR -> pin 2.
// The driver's current limit (Vref) must be set for the specific motor.
// Steps per turn depends on the motor (e.g., 200 for 1.8°) and microstepping.
// This sketch uses 200 steps per turn (full step) for simplicity.
// If using microstepping, multiply 200 by the microstep factor (e.g., 8 for 1/8 step).

#include <AccelStepper.h>

const int stepPin = 3;
const int dirPin = 2;
const int enablePin = 4; // Optional: connect to pin 4 to enable/disable driver

// Define steps per turn. Adjust if using microstepping or a different motor.
// 200 steps = 1.8 degree motor, full step.
const long stepsPerTurn = 200L; 
// Total steps to move back and forth
const long moveSteps = 800L;

// Create AccelStepper instance in DRIVER mode
AccelStepper stepper(AccelStepper::DRIVER, stepPin, dirPin);

void setup() {
  // Initialize enable pin if used (LOW enables the driver)
  if (enablePin > 0) {
    pinMode(enablePin, OUTPUT);
    digitalWrite(enablePin, LOW);
  }

  // Set maximum speed (steps per second)
  stepper.setMaxSpeed(1000);

  // Set acceleration (steps per second squared) for smooth motion
  stepper.setAcceleration(500);

  // Move to the target position (800 steps forward)
  stepper.moveTo(moveSteps);
}

void loop() {
  // Run the stepper
  stepper.run();

  // Check if the current move is complete
  if (stepper.distanceToGo() == 0) {
    // Reverse direction: move back to the start (0 steps)
    // Note: moveTo() sets an absolute position. 
    // If we are at 800, moving to 0 is 800 steps back.
    stepper.moveTo(0);
  }
}
END

MAKE CODE: P1AM-100 Motor Start/Stop Seal-in
// P1AM-100: Motor control with Start (NO) on ch1, Stop (NC) on ch2, and Motor Contactor on ch1.
// Slot 1: Discrete Input (Start, Stop, Overload)
// Slot 2: Discrete Output (Motor Contactor)
#include <P1AM.h>

const int inSlot = 1;
const int outSlot = 2;
const int pinStart = 1;
const int pinStop = 2;
const int pinMotor = 1;

bool motorRunning = false;

void setup() {
  Serial.begin(115200);
  while (!P1.init()) {
    ; // Wait for modules to initialize
  }
}

void loop() {
  // Read inputs: Start is NO (true when pressed), Stop is NC (true when not pressed)
  bool startPressed = P1.readDiscrete(inSlot, pinStart);
  bool stopPressed = !P1.readDiscrete(inSlot, pinStop); // Invert NC logic: false if pressed

  // Seal-in logic: Run if Start is pressed OR currently running, AND Stop is not pressed
  if (startPressed || motorRunning) {
    motorRunning = true;
  }
  if (stopPressed) {
    motorRunning = false;
  }

  // Write output: Motor Contactor
  P1.writeDiscrete(motorRunning, outSlot, pinMotor);
}
END

MAKE CODE: Average temperature from CSV
python
import csv
import sys

def main():
    if len(sys.argv) < 2:
        print("usage: python3 avg_temp.py readings.csv")
        return

    path = sys.argv[1]
    temps = []

    try:
        with open(path, newline='') as f:
            reader = csv.DictReader(f)
            for row in reader:
                try:
                    # Assuming the column is named 'temp'
                    val = float(row['temp'])
                    temps.append(val)
                except (KeyError, ValueError):
                    continue # Skip rows with missing or non-numeric temp

        if temps:
            avg = sum(temps) / len(temps)
            print(f"Average temperature: {avg}")
        else:
            print("No valid temperature data found.")

    except FileNotFoundError:
        print(f"Error: File '{path}' not found.")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()
END

